use std::io::{Read, Write, BufRead, BufReader};
use std::net::{TcpListener, TcpStream};
use std::sync::Arc;
use std::collections::HashMap;
use std::time::SystemTime;

/// LDAP proxy with audit logging and query normalization
/// Supports BIND, SEARCH, and UNBIND operations

const LDAP_BIND: u8 = 0x60;
const LDAP_SEARCH: u8 = 0x63;
const LDAP_UNBIND: u8 = 0x42;

struct AuditEntry {
    timestamp: u64,
    client_addr: String,
    operation: String,
    filter: String,
    sanitized: bool,
}

struct LdapFilter {
    raw: String,
    components: Vec<String>,
}

impl LdapFilter {
    fn parse(input: &str) -> Self {
        let components: Vec<String> = input
            .split('&')
            .map(|s| s.trim().to_string())
            .collect();
        LdapFilter {
            raw: input.to_string(),
            components,
        }
    }
}

/// Sanitization layer - removes dangerous metacharacters
fn sanitize_ldap_value(value: &str) -> String {
    let mut result = String::with_capacity(value.len());
    for ch in value.chars() {
        match ch {
            '\\' => result.push_str("\\5c"),
            '*' => result.push_str("\\2a"),
            '(' => result.push_str("\\28"),
            ')' => result.push_str("\\29"),
            '\0' => result.push_str("\\00"),
            _ => result.push(ch),
        }
    }
    result
}

/// Normalizes Unicode characters to their ASCII equivalents
/// for consistent filter processing
fn normalize_unicode(input: &str) -> String {
    let mut output = String::with_capacity(input.len());
    for ch in input.chars() {
        match ch {
            '\u{FF08}' => output.push('('),  // fullwidth left paren
            '\u{FF09}' => output.push(')'),  // fullwidth right paren
            '\u{FF0A}' => output.push('*'),  // fullwidth asterisk
            '\u{FF3C}' => output.push('\\'), // fullwidth reverse solidus
            '\u{2217}' => output.push('*'),  // asterisk operator
            '\u{FE61}' => output.push('*'),  // small asterisk
            '\u{207D}' => output.push('('),  // superscript left paren
            '\u{207E}' => output.push(')'),  // superscript right paren
            _ => output.push(ch),
        }
    }
    output
}

/// Build the final LDAP search filter from user input
/// Pipeline: normalize -> parse -> sanitize -> reconstruct
fn build_search_filter(base_filter: &str, user_input: &str) -> String {
    // Step 1: Normalize unicode to ASCII equivalents
    let normalized = normalize_unicode(user_input);

    // Step 2: Parse into filter components
    let filter = LdapFilter::parse(&normalized);

    // Step 3: Sanitize each component
    let sanitized_components: Vec<String> = filter.components
        .iter()
        .map(|c| sanitize_ldap_value(c))
        .collect();

    // Step 4: Reconstruct the filter
    let user_part = sanitized_components.join("&");

    format!("(&{}({}))", base_filter, user_part)
}

struct ProxyConfig {
    listen_addr: String,
    backend_addr: String,
    base_dn: String,
    allowed_base_filter: String,
}

struct ProxySession {
    config: Arc<ProxyConfig>,
    audit_log: Vec<AuditEntry>,
    client_addr: String,
}

impl ProxySession {
    fn new(config: Arc<ProxyConfig>, client_addr: String) -> Self {
        ProxySession {
            config,
            audit_log: Vec::new(),
            client_addr,
        }
    }

    fn handle_search(&mut self, raw_filter: &str) -> Result<String, String> {
        // Audit the raw input
        let entry = AuditEntry {
            timestamp: SystemTime::now()
                .duration_since(SystemTime::UNIX_EPOCH)
                .unwrap_or_default()
                .as_secs(),
            client_addr: self.client_addr.clone(),
            operation: "SEARCH".to_string(),
            filter: raw_filter.to_string(),
            sanitized: true,
        };
        self.audit_log.push(entry);

        // Build the safe filter
        let final_filter = build_search_filter(
            &self.config.allowed_base_filter,
            raw_filter,
        );

        // Validate filter structure before forwarding
        if !validate_filter_structure(&final_filter) {
            return Err("Invalid filter structure after processing".to_string());
        }

        Ok(final_filter)
    }
}

/// Validates that parentheses are balanced in the final filter
fn validate_filter_structure(filter: &str) -> bool {
    let mut depth: i32 = 0;
    for ch in filter.chars() {
        match ch {
            '(' => depth += 1,
            ')' => {
                depth -= 1;
                if depth < 0 {
                    return false;
                }
            }
            _ => {}
        }
    }
    depth == 0
}

fn main() {
    let config = Arc::new(ProxyConfig {
        listen_addr: "127.0.0.1:3890".to_string(),
        backend_addr: "127.0.0.1:389".to_string(),
        base_dn: "dc=example,dc=com".to_string(),
        allowed_base_filter: "(objectClass=person)".to_string(),
    });

    let listener = TcpListener::bind(&config.listen_addr)
        .expect("Failed to bind");

    println!("LDAP Proxy listening on {}", config.listen_addr);

    for stream in listener.incoming() {
        match stream {
            Ok(client) => {
                let cfg = config.clone();
                std::thread::spawn(move || {
                    let addr = client.peer_addr()
                        .map(|a| a.to_string())
                        .unwrap_or_else(|_| "unknown".to_string());
                    let mut session = ProxySession::new(cfg, addr);
                    handle_client(client, &mut session);
                });
            }
            Err(e) => eprintln!("Connection error: {}", e),
        }
    }
}

fn handle_client(mut client: TcpStream, session: &mut ProxySession) {
    let mut buf = [0u8; 4096];
    loop {
        match client.read(&mut buf) {
            Ok(0) => break,
            Ok(n) => {
                // Simplified: extract filter from search request
                if n > 2 && buf[0] == LDAP_SEARCH {
                    let filter_str = String::from_utf8_lossy(&buf[2..n]);
                    match session.handle_search(&filter_str) {
                        Ok(safe_filter) => {
                            // Forward to backend (simplified)
                            let _ = client.write(safe_filter.as_bytes());
                        }
                        Err(e) => {
                            let _ = client.write(e.as_bytes());
                        }
                    }
                }
            }
            Err(_) => break,
        }
    }
}
